<?php declare(strict_types=1);namespace NpmGateway\Notifications;use NpmGateway\Services\HrEmployeeNotificationConfig;use NpmGateway\ValueObjects\{GatewayEmailMessage};use PHPMailer\PHPMailer\PHPMailer;
