 public function submitted(array$order):bool{$mode=($this->config['test_mode']??false)===true?'test':'production';$to=trim((string)($mode==='test'?($this->config['test_email']??''):($this->config['recipient_email']??'')));if(filter_var($to,FILTER_VALIDATE_EMAIL)===false)return$this->fail('recipient_unavailable',$mode);try{$content=$this->renderer->render(new GatewayEmailMessage('Property supply request submitted.','SUPPLY ORDER','Supply Order Submitted',$order['property_name'],'Submitted','informational',[['label'=>'Property','value'=>$order['property_name'],'emphasized'=>true],['label'=>'Submitted By','value'=>$order['submitted_by_name']],['label'=>'Submitted At','value'=>$this->date($order['submitted_at'])]],[['title'=>'Supplies Requested','trusted_sanitized_html'=>$order['request_html'],'plain_text'=>$order['request_text']]],'View Supply Order',rtrim((string)$this->config['app_url'],'/').'/community-actions/'.$order['property_slug'].'/supply-orders/'.$order['public_id']));$subject='Supply Order Submitted — '.$order['property_name'];if($this->delivery)return(bool)($this->delivery)($to,$subject,$content['html'],$content['text']);$smtp=HrEmployeeNotificationConfig::fromArray((array)$this->config['smtp']);$mail=new PHPMailer(true);$mail->isSMTP();$mail->Host=$smtp->host;$mail->Port=$smtp->port;$mail->SMTPAuth=true;$mail->Username=$smtp->username;$mail->Password=$smtp->password;$mail->SMTPSecure=$smtp->secure==='ssl'?PHPMailer::ENCRYPTION_SMTPS:PHPMailer::ENCRYPTION_STARTTLS;$mail->CharSet=PHPMailer::CHARSET_UTF8;$mail->setFrom($smtp->fromAddress,$smtp->fromName);$mail->addAddress($to);$mail->Subject=$subject;$mail->isHTML(true);$mail->Body=$content['html'];$mail->AltBody=$content['text'];$mail->send();return true;}catch(\Throwable$e){return$this->fail('delivery_failure',$mode,$e);}}
